private List<VarCodeGen> getTaskFreeVars(Node n) {
    List<VarCodeGen> vcgs = new ArrayList<VarCodeGen>();
    vcgs.add(new VarCodeGen.BaseTaskVar(this));
    vcgs.addAll(getFreeVars(n));
    return vcgs;
}

